    const [left, leftInversions] = countInversions(nums.slice(0, mid));
    const [right, rightInversions] = countInversions(nums.slice(mid));

    const merged = [];
    let totalInversions = leftInversions + rightInversions;
    let i = 0;
    let j = 0;

